export const TERM_BY_KEY = new Map(
  POJU_TERMS.map((t) => [`${t.ns}:${t.slug}`, t] as const),
);

/**
 * Slug → term (slugs are globally unique via qm_/gp_/stem_ prefixes).
 * Markers need not carry ns.
 */
export const TERM_BY_SLUG = new Map(POJU_TERMS.map((t) => [t.slug, t] as const));

export const TERM_BY_TRADITIONAL = new Map(
  POJU_TERMS.map((t) => [`${t.ns}:${t.traditional}`, t] as const),
);

const LOCALE_FALLBACK: TermLocale[] = ["en", "zh"];

export function toTermLocale(locale: string): TermLocale {
  const base = (locale || "en").toLowerCase().split(/[-_]/)[0]!;
  if (base === "zh" || base === "en" || base === "es" || base === "de" || base === "fr") {
    return base;
  }
  return "en";
}

function pickLocale(bag: Record<TermLocale, string>, locale: string): string {
  const loc = toTermLocale(locale);
  const direct = (bag[loc] || "").trim();
  if (direct) return direct;
  for (const fb of LOCALE_FALLBACK) {
    const v = (bag[fb] || "").trim();
    if (v) return v;
  }
  return "";
}

/** Soft label from SSOT by slug (preferred) or ns+slug. */
export function termOf(slug: string, locale: string): string | null;
export function termOf(ns: TermNs, slug: string, locale: string): string | null;
export function termOf(
  nsOrSlug: TermNs | string,
  slugOrLocale: string,
  locale?: string,
): string | null {
  if (locale === undefined) {
    const t = TERM_BY_SLUG.get(nsOrSlug);
    if (!t) return null;
    return pickLocale(t.term, slugOrLocale) || null;
  }
  const t = TERM_BY_KEY.get(`${nsOrSlug as TermNs}:${slugOrLocale}`);
  if (!t) return null;
  return pickLocale(t.term, locale) || null;
}

/** Fixed gloss from SSOT by slug (preferred) or ns+slug. */
export function glossOf(slug: string, locale: string): string | null;
export function glossOf(ns: TermNs, slug: string, locale: string): string | null;
export function glossOf(
  nsOrSlug: TermNs | string,
  slugOrLocale: string,
  locale?: string,
): string | null {
  if (locale === undefined) {
    const t = TERM_BY_SLUG.get(nsOrSlug);
    if (!t) return null;
    return pickLocale(t.definition, slugOrLocale) || null;
  }
  const t = TERM_BY_KEY.get(`${nsOrSlug as TermNs}:${slugOrLocale}`);
  if (!t) return null;
  return pickLocale(t.definition, locale) || null;
}

/** Lookup by slug alone (slugs are unique across landed namespaces). */
export function pojuTermBySlug(slug: string): PojuTerm | undefined {
  return TERM_BY_SLUG.get(slug);
}

let _missingNsWarnCount = 0;

/** Test/telemetry helper — how many times legacy lookup omitted namespace this process. */
export function pojuTermMissingNamespaceWarnCount(): number {
  return _missingNsWarnCount;
}

/**
 * @deprecated Prefer `resolvePojuTerm(input, { namespace })` from `@/lib/glossary/term-resolve`.
 * Kept for migration; return semantics unchanged. Omitting `ns` may cross-ns first-match.
 */
export function pojuTermByTraditional(
  traditional: string,
  ns?: TermNs,
): PojuTerm | undefined {
  if (ns === undefined) {
    _missingNsWarnCount += 1;
    if (
      typeof process !== "undefined" &&
      process.env.NODE_ENV !== "production" &&
      _missingNsWarnCount <= 20
    ) {
      console.warn(
        `[terms] pojuTermByTraditional("${traditional}") called without namespace — migrate to resolvePojuTerm(input, { namespace })`,
      );
    }
  }
  const names = termHanVariants(traditional);
  for (const word of names) {
    const exact = ns
      ? TERM_BY_TRADITIONAL.get(`${ns}:${word}`)
      : POJU_TERMS.find((t) => t.traditional === word);
    if (exact) return exact;
    const aliased = POJU_TERMS.find(
      (t) =>
        (!ns || t.ns === ns) &&
        t.aliases?.some((a) => termHanVariants(a).includes(word)),
    );
    if (aliased) return aliased;
  }
  return undefined;
}

/**
 * Soft-label name table (slug + ns + soft only — no definitions).
 * @deprecated Phase 5: prefer `buildTermContextForFacts` / `buildTermContextPromptFromStructured`
 * from `@/lib/glossary/term-context-for-facts` — inject only terms present in this run's facts.
 * Do not dump the full SSOT into prompts.
 */
export function buildPojuTermsPromptTable(locale: string, namespaces?: TermNs[]): string {
  const loc = toTermLocale(locale);
  const nsFilter = namespaces?.length ? new Set(namespaces) : null;
  const rows = POJU_TERMS.filter((t) => !nsFilter || nsFilter.has(t.ns))
    .map((t) => {
      const soft = pickLocale(t.term, loc);
      return `| \`${t.slug}\` | ${t.ns} | **${soft}** |`;
    })
    .join("\n");
  return rows;
}

/** @deprecated Use POJU_TERMS */
export const POJULIFE_TERMS = POJU_TERMS;

